"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78233"],{48052(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.ato_normativo.vinculo_exige_registro_pelo_dominio","status":422,"titulo":"Ato vinculado a esta entidade s\xf3 pode ser registrado pelo m\xf3dulo dono do objeto"},"descricao":{"codigo":"uniplus.publicacoes.ato_normativo.vinculo_exige_registro_pelo_dominio","requisitos":["UNI-REQ-0155","UNI-REQ-0156"],"oQueAconteceu":["A opera\xe7\xe3o administrativa de Publica\xe7\xf5es recebeu um ato normativo vinculado a\\num **processo seletivo**. O v\xednculo pode vir declarado na requisi\xe7\xe3o, ou ser\\n**herdado**: ao retificar um ato (`atoRetificadoId`), a retifica\xe7\xe3o trata do\\nmesmo objeto do ato retificado, e o ato retificado j\xe1 era de um processo\\nseletivo.","Essa opera\xe7\xe3o recebe s\xf3 os metadados e o hash do documento, n\xe3o o arquivo. Um\\nato de processo seletivo registrado por ali ficaria **sem documento**. Quem\\nguarda o arquivo e o leva ao acervo p\xfablico \xe9 o m\xf3dulo dono do objeto, a\\nSele\xe7\xe3o.","A mensagem de detalhe vale para qualquer objeto cujo dom\xednio registra os pr\xf3prios atos e nomeia o r\xf3tulo da entidade vinculada\\n(`PROCESSO_SELETIVO`), explicando que os atos desse objeto s\xe3o registrados pelo\\npr\xf3prio dom\xednio, inclusive a retifica\xe7\xe3o.","A recusa vale para o v\xednculo **declarado** e para o v\xednculo **herdado** da\\nretifica\xe7\xe3o. O declarado \xe9 recusado antes de qualquer consulta ao banco e da\\nvalida\xe7\xe3o da cadeia. O herdado s\xf3 se conhece depois de resolvida a cadeia, ent\xe3o\\nsai **depois** destas recusas, que t\xeam preced\xeancia:","- [`tipo_sem_versao_vigente`](/erros/uniplus.publicacoes.ato_normativo.tipo_sem_versao_vigente);\\n- [`versao_do_objeto_incompleta`](/erros/uniplus.publicacoes.ato_normativo.versao_do_objeto_incompleta);\\n- [`ato_retificado_nao_encontrado`](/erros/uniplus.publicacoes.ato_normativo.ato_retificado_nao_encontrado);\\n- [`classe_congelamento_divergente`](/erros/uniplus.publicacoes.ato_normativo.classe_congelamento_divergente);\\n- [`ato_ja_retificado`](/erros/uniplus.publicacoes.ato_normativo.ato_ja_retificado).","O status \xe9 **422** porque o pedido, tal como chega ou como resulta da heran\xe7a,\\npede o que esta opera\xe7\xe3o n\xe3o pode fazer; n\xe3o h\xe1 conflito com estado gravado."],"comoResolver":["Publique o ato pela **Sele\xe7\xe3o**, na p\xe1gina \\"Publica\xe7\xf5es\\" do processo\\nseletivo. Ela guarda o arquivo e o leva ao acervo p\xfablico, e vale tamb\xe9m para\\nerrata e retifica\xe7\xe3o de um ato que j\xe1 tem esse v\xednculo. N\xe3o reenvie o mesmo\\npedido \xe0 opera\xe7\xe3o de Publica\xe7\xf5es."],"ondeAparece":["Registro de ato normativo vinculado a processo seletivo","Registro de ato normativo que retifica ato vinculado a processo seletivo"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Ato normativo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);